WITH cleaned AS (SELECT id, reading_ts, humidity, pressure, status_bits, firmware, humidity / NULLIF(status_bits, 0) AS humidity_per_status_bits FROM device_readings WHERE status_bits BETWEEN 6 AND 8) SELECT id, reading_ts, status_bits, LEAD(status_bits) OVER w_running AS next_status_bits, LAG(pressure) OVER w_running AS prev_pressure, ROW_NUMBER() OVER w_running AS row_seq FROM cleaned WHERE reading_ts >= '2024-01-24' WINDOW w_running AS (ORDER BY status_bits, id)
